mapper.select:
SELECT f.*, c.title, c.user_id AS conv_user_id, g.name AS group_name FROM ai_favorite f INNER JOIN ai_conversation c ON f.conversation_id = c.id LEFT JOIN ai_favorite_group g ON f.group_id = g.id WHERE f.user_id = #{userId}
AND f.group_id = #{groupId}
AND c.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY f.create_time DESC
